<template>
<section class="cajas"><header><h1>Cajas por punto de venta</h1><p>Fábrica, sucursales y stands · apertura, cierre y conciliación</p></header>
<div v-if="error" class="error">{{error}}</div><div v-if="ok" class="ok">{{ok}}</div>
<div class="panel"><label>Ubicación <select v-model="ubicacion" @change="cargar"><option value="">Seleccione una ubicación</option><option v-for="u in ubicaciones" :key="u.id_ubicacion" :value="u.id_ubicacion">{{u.nombre}} · {{u.tipo}}</option></select></label>
<div v-if="ubicacion && !abierta" class="fila"><label>Efectivo inicial (Bs)<input v-model.number="inicial" type="number" min="0" step="0.01" /></label><button :disabled="ocupado" @click="abrir">Abrir caja</button></div>
<div v-if="abierta"><h2>Caja #{{abierta.caja.id_caja}} · ABIERTA</h2><div class="metricas"><div>Inicial <strong>Bs {{abierta.caja.monto_inicial}}</strong></div><div>Efectivo cobrado <strong>Bs {{abierta.cobros.efectivo}}</strong></div><div>QR <strong>Bs {{abierta.cobros.qr}}</strong></div><div>Transferencias <strong>Bs {{abierta.cobros.transferencia}}</strong></div><div>Esperado en efectivo <strong>Bs {{abierta.efectivo_esperado_actual}}</strong></div></div><div class="fila"><label>Efectivo contado (Bs)<input v-model.number="contado" type="number" min="0" step="0.01" /></label><label>Observación de cierre<textarea v-model="observacion" rows="2" placeholder="Obligatoria si hay diferencias"></textarea></label><button :disabled="ocupado" @click="cerrar">Cerrar caja</button></div></div></div>
<div v-if="ubicacion" class="panel"><div class="fila"><h2>Historial de cajas</h2><button @click="cargar">Actualizar</button></div><div class="tabla"><table><thead><tr><th>Caja</th><th>Estado</th><th>Apertura</th><th>Cierre</th><th>Inicial</th><th>Efectivo esperado</th><th>Contado</th><th>Diferencia</th></tr></thead><tbody><tr v-for="x in historial" :key="x.caja.id_caja"><td>#{{x.caja.id_caja}}</td><td>{{x.caja.estado}}</td><td>{{fecha(x.caja.fecha_apertura)}}</td><td>{{fecha(x.caja.fecha_cierre)}}</td><td>{{x.caja.monto_inicial}}</td><td>{{x.caja.efectivo_esperado ?? x.efectivo_esperado_actual}}</td><td>{{x.caja.efectivo_contado ?? '—'}}</td><td>{{x.caja.diferencia ?? '—'}}</td></tr><tr v-if="!historial.length"><td colspan="8">Sin sesiones registradas.</td></tr></tbody></table></div></div>
</section>
</template>
<script>
import api from '../../services/api';
export default {data(){return{ubicaciones:[],ubicacion:'',historial:[],inicial:0,contado:0,observacion:'',error:'',ok:'',ocupado:false}},computed:{abierta(){return this.historial.find(x=>x.caja.estado==='ABIERTA')}},async mounted(){try{this.ubicaciones=(await api.get('/api/cajas-punto-venta/ubicaciones')).data}catch(e){this.error=this.msg(e)}},methods:{msg(e){return Object.values(e.response?.data?.errors||{}).flat().join(' ')||e.response?.data?.message||'No se pudo completar la operación.'},fecha(x){return x?new Date(x).toLocaleString('es-BO'):'—'},async cargar(){this.error='';this.ok='';this.historial=[];if(!this.ubicacion)return;try{this.historial=(await api.get('/api/cajas-punto-venta',{params:{id_ubicacion:this.ubicacion}})).data}catch(e){this.error=this.msg(e)}},async abrir(){if(!confirm('¿Confirmar apertura de caja?'))return;this.ocupado=true;this.error='';try{await api.post('/api/cajas-punto-venta/abrir',{id_ubicacion:this.ubicacion,monto_inicial:this.inicial});await this.cargar();this.ok='Caja abierta.'}catch(e){this.error=this.msg(e)}finally{this.ocupado=false}},async cerrar(){if(!this.abierta||!confirm('¿Cerrar esta caja? Esta acción no se puede revertir.'))return;this.ocupado=true;this.error='';try{await api.post(`/api/cajas-punto-venta/${this.abierta.caja.id_caja}/cerrar`,{efectivo_contado:this.contado,observacion:this.observacion});await this.cargar();this.ok='Caja cerrada y conciliada.';this.observacion=''}catch(e){this.error=this.msg(e)}finally{this.ocupado=false}}}}
</script>
<style scoped>
.cajas{max-width:1250px;margin:auto;padding:25px;color:#0c3025}header{background:#0c3025;color:white;border-radius:16px;padding:25px}header h1{margin:0}header p{color:#d5e7d9}.panel{background:white;padding:22px;border:1px solid #dbe9df;border-radius:15px;margin-top:20px;box-shadow:0 5px 24px #0c30250c}.fila{display:flex;gap:16px;align-items:end;flex-wrap:wrap;margin-top:15px}label{font-weight:700;display:block}input,select,textarea{display:block;margin-top:8px;padding:10px;border:1px solid #c4d8cb;border-radius:8px;min-width:180px}button{background:#f47b20;border:0;color:white;border-radius:9px;padding:12px 18px;font-weight:700;cursor:pointer}button:disabled{opacity:.5}.metricas{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:12px}.metricas>div{background:#edf5ef;padding:15px;border-radius:9px}.metricas strong{display:block;font-size:20px}.tabla{overflow:auto}table{border-collapse:collapse;width:100%;margin-top:10px}td,th{padding:11px;text-align:left;border-bottom:1px solid #e1ece5}th{background:#124734;color:white}.error,.ok{padding:12px;margin-top:12px;border-radius:8px}.error{background:#ffeaea;color:#8e2222}.ok{background:#e4f5e9;color:#17613b}
</style>
